#!/usr/bin/env python3
"""Copy verified, unchanged block10 metadata into a new private checkpoint.

Raw tar/payload stay ignored. All source JSON/report path strings remain intact.
"""
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import sys

sys.dont_write_bytecode = True
ROOT=Path('/Users/danielejiofor/AIRFLOW/gpu-spark-polars-study')
OUT=Path(__file__).resolve().parent
CHECKPOINT=ROOT/'evidence-research/20261028/gclocker100-block10-raw-checkpoint'
RAW=ROOT/'rerun/gclocker100-20261027/raw-backups'
OBS=ROOT/'rerun/gclocker100-20261027/observations/20261028T232757Z'
ARCHIVE=ROOT/'evidence-research/20261027/h100-confirmatory-gclocker100-v1'

def sha(path):
    h=hashlib.sha256()
    with Path(path).open('rb') as f:
        for chunk in iter(lambda:f.read(8*1024*1024),b''):h.update(chunk)
    return h.hexdigest()

def write(path,value):
    with path.open('xb') as f:f.write((json.dumps(value,indent=2,sort_keys=True,allow_nan=False)+'\n').encode())

def main():
    summary=json.loads((OUT/'PARTIAL_BLOCK10_INDEPENDENT_SUMMARY_WITH_GATES.json').read_bytes())
    assert summary['status']=='PARTIAL_BLOCK_ONLY' and summary['checks_status']=='NO_FINDINGS' and summary['findings']==[]
    assert all(sha(Path(proof['path'])) == proof['sha256'] for proof in summary['partial_reports'])
    assert summary['frozen_selected_block_validation']['sha256'] == sha(OUT/'FROZEN_SELECTED_BLOCK10_AUDITS.json')
    assert summary['counts']=={'sessions':40,'successful_outputs':936,'warmup_outputs':234,'measured_outputs':702,'translation_rejections':6,'successful_complex_cleanups':336,'failed_complex_cleanups':6}
    sources={'BACKUP_CONTROL.json':RAW/'block-10.json','BACKUP_MANIFEST.json':RAW/'block-10/BACKUP_MANIFEST.json','OFFHOST_VERIFIED.json':RAW/'block-10.verified.json','JOURNAL.json':RAW/'block-10/campaign-results/journal.json','LAST_SESSION.json':RAW/'block-10/campaign-results/block-10-complex-sf100-spark_gpu/attempt-001/session.json','campaign.json':RAW/'block-10/campaign.json','campaign.json.sha256':RAW/'block-10/campaign.json.sha256','CANONICAL_PRESTART_MANIFEST.json':ARCHIVE/'PRESTART_MANIFEST.json','EXECUTION_PROFILE.json':ARCHIVE/'EXECUTION_PROFILE.json','profile-observation/OBSERVATION.json':OBS/'OBSERVATION.json','profile-observation/EXECUTION_PROFILE_GATES.jsonl':OBS/'EXECUTION_PROFILE_GATES.jsonl'}
    sources.update({'audit/'+p.name:p for p in sorted(OUT.iterdir()) if p.is_file()})
    identities={name:{'original_path':str(path.relative_to(ROOT)),'sha256':sha(path),'bytes':path.stat().st_size} for name,path in sources.items()}
    CHECKPOINT.mkdir()
    for name,path in sources.items():
        target=CHECKPOINT/name
        target.parent.mkdir(parents=True,exist_ok=True)
        with target.open('xb') as f:f.write(path.read_bytes())
        assert sha(target)==identities[name]['sha256']==sha(path),name
    result={'schema_version':'h100-partial-raw-checkpoint-v1','status':'OFFHOST_BLOCK_VERIFIED','independent_validation_status':'PARTIAL_BLOCK_ONLY','checks_status':'NO_FINDINGS','scope':'Tenth fixed-profile recovery block only; no complete-study result, statistical analysis, performance estimate or live-host-idle claim','created_at_utc':datetime.now(timezone.utc).isoformat(),'campaign_id':summary['campaign_id'],'campaign_sha256':summary['campaign_sha256'],'prestart_sha256':summary['prestart_sha256'],'execution_profile_sha256':summary['execution_profile_sha256'],'block_id':'block-10','planned_sessions':400,'original_journal_completed_at_utc':summary['original_journal_completed_at_utc'],'journal_succeeded_sessions':400,'snapshot_pending_sessions':0,'audited_sessions_in_this_checkpoint':40,'prior_sessions_not_newly_oracle_or_jvm_revalidated':360,'counts_in_this_block':summary['counts'],'raw_archive_location':str((RAW/'block-10.tar').relative_to(ROOT)),'raw_archive_sha256':summary['transport']['tar_sha256'],'raw_archive_bytes':summary['transport']['tar_bytes'],'raw_files':1355,'raw_regular_files_including_manifest':1356,'journal_sha256':sha(RAW/'block-10/campaign-results/journal.json'),'frozen_validation_method':'Unchanged archived C84 audit_session on selected40 original sessions with eight canonical oracles, retaining actual original400-session plan and400-success journal; no full --partial CLI against missing prior payloads','formal_spark_driver_logs_verified_in_this_block':16,'session_configuration_and_python_inventories_verified':40,'profile_observation_records':22,'profile_receipts_verified_through_this_block':22,'profile_observation_log_sha256':summary['profile_receipt_proof']['gate_log_sha256'],'profile_observation_log_bytes':53363,'separately_observed_later_receipt':None,'final_profile_pair_present':False,'statistical_analysis_performed':False,'audit_environment':'Successful audit used existing /tmp/h100-analysis-audit-venv/bin/python -B with no install or network. This local audit executed no engine or query.','orchestration_wall_time_preservation':summary['orchestration_wall_time_preservation'],'block_timestamps':summary['block_timestamps'],'independent_summary_sha256':sha(OUT/'PARTIAL_BLOCK10_INDEPENDENT_SUMMARY_WITH_GATES.json'),'frozen_selected_audits_sha256':sha(OUT/'FROZEN_SELECTED_BLOCK10_AUDITS.json'),'local_session_transport_audit_sha256':sha(OUT/'PARTIAL_BLOCK_AUDIT.json'),'jvm_runtime_audit_sha256':sha(OUT/'PARTIAL_BLOCK10_JVM_AUDIT.json'),'source_copies':identities,'limitations':summary['limitations']}
    write(CHECKPOINT/'CHECKPOINT_SUMMARY.json',result)
    readme='# Recovery block 10 raw checkpoint\n\nStatus is **PARTIAL_BLOCK_ONLY, NO_FINDINGS**. All 40 selected block10 sessions and their 936 successful outputs were independently checked locally with the untouched archived C84 `research_validate.audit_session` function and all eight canonical SQL oracles. The six specific strict Polars GPU q13/window translation rejections are warmup/trial0 outcomes at SF30/100/300; all 336 successful and six failed-query complex cleanup records match. The actual original 400-session plan and original block-end journal recording 400 successes/0 future planned sessions remain unchanged. This isolated transport contains only block10, so no full frozen `--partial` CLI run against missing earlier payloads is claimed. No statistical analysis or performance finding is produced.\n\nThe complete 1,044,264,960-byte raw tar has SHA256 `1943788b15f270066de43b3043827e8acb3c15962d2a878b36e85dbee68f32cf`. A fresh temporary extraction and the original extracted directory were independently checked against original control/receipt/manifest bytes: all 1,355 payload files plus the manifest match. The tar and full payload remain in ignored local operational storage at the exact paths in CHECKPOINT_SUMMARY.json. Original JSON/report path strings are preserved verbatim in this checkpoint; canonical prestart is separately tracked and unchanged.\n\nAll 40 archived runtime/configuration inventories and 16 actual formal Spark child JVM flag tables match the sealed profile: GCLockerRetryAllocationCount 100, MaxHeapSize 103079215104 bytes (96 GiB), G1GC, unlocked diagnostic options and PrintFlagsFinal. Installed VM Java binaries and live processes were not accessed by this audit.\n\nThe independently captured 22-record formal profile observation is separate from the raw transport. Its all twenty-two receipts retain the exact two-record sealed readiness prefix and match the sealed Java/environment profile; recorded before/after receipts bracket blocks01/02/03/04/05/06/07/08/09/10. This boundary capture contains no final-before/final-after pair; those receipts remain separate from this audit. This does not establish current host idleness. Original journal items for the 360 earlier block01/02/03/04/05/06/07/08/09 sessions are unchanged relative to their original block-end journals; their outputs and JVM logs are not newly revalidated or counted here.\n\nAll 40 original block10 attempt records and their orchestration wall times are preserved verbatim in the original journal and independently compared with the raw session records. LAST_SESSION.json is an exact byte copy. The final session ended at `2026-10-28T23:26:10.952925+00:00`; the recorded after-profile receipt completed at `2026-10-28T23:26:11.485998+00:00`; manifest/control creation followed at `23:26:13.310832`/`23:26:15.525768`; offhost verification completed at `23:27:54.879158`. These exact historical timestamps are preserved without any causal, pacing or performance inference. This checkpoint changes no raw timestamps.\n\nThe successful local audit used the existing `/tmp/h100-analysis-audit-venv/bin/python -B`; AUDIT_RUNTIME.json records its versions. No dependency installation, network, API, VM operation, worker/query execution, restart or performance analysis was used by this audit. Three successful verification logs and all exact audit scripts/reports are preserved under audit/. LOCAL_SETUP_DIAGNOSTICS.json preserves the initial benign missing-glob observation before the block10 receipt existed; it is not a benchmark or transport failure. The profile observation metadata records the separate read-only capture provenance; this checkpoint operation only reads its local files.\n\nThis checkpoint does not establish a complete-study result. The original boundary journal declares 400 successful sessions, with completed_at_utc still null; this audit independently rechecks only the 40 block10 payload sessions. The final profile pair, true post-final input-byte gate, complete 400-session reconstruction/replay/analysis, separate contention disposition and same-scheduler handoff/resume proof, full paper and public webpage, durable private evidence retrieval, and conditional retirement remain outside this checkpoint. This local checkpoint neither changes nor assesses current live workloads.\n\nCHECKPOINT_MANIFEST.json lists the SHA256 and byte count of every checkpoint file except itself. `audit/verify_block10_checkpoint.py` verifies the file set/checksums, original source copies and that every listed file is tracked in Git. Verification logs are intentionally force-added despite the global *.log ignore rule. No raw tar or payload is committed, and no push is performed by this checkpoint operation.\n'
    with (CHECKPOINT/'README.md').open('x') as f:f.write(readme)
    files={str(p.relative_to(CHECKPOINT)):{'sha256':sha(p),'bytes':p.stat().st_size} for p in sorted(CHECKPOINT.rglob('*')) if p.is_file()}
    write(CHECKPOINT/'CHECKPOINT_MANIFEST.json',{'schema_version':'h100-private-checkpoint-inventory-v1','status':'PARTIAL_BLOCK_ONLY','campaign_sha256':summary['campaign_sha256'],'block_id':'block-10','scope':'Checksums of private checkpoint metadata; excludes this manifest itself. Raw tar/payload stay ignored.','files':files})
    print(json.dumps({'checkpoint':str(CHECKPOINT),'files_including_manifest':len(files)+1,'manifest_sha256':sha(CHECKPOINT/'CHECKPOINT_MANIFEST.json'),'summary_sha256':sha(CHECKPOINT/'CHECKPOINT_SUMMARY.json'),'independent_summary_sha256':result['independent_summary_sha256']},sort_keys=True))

if __name__=='__main__':main()
